    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([5]), fmt([9, 10, 11]), fmt([1, 2]), fmt([5, 5, 5]), fmt([1, 2, 4, 8]), fmt([0, 0, 1]),
             fmt([32767, 0]), fmt([1, 2, 4, 8, 16, 32767])]
    for n in (2, 3, 4, 6, 8, 10, 12):
        for hi in (3, 15, 100):
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    V = 32767
    tests.append(fmt([rng.randint(0, V) for _ in range(200000)]))
    tests.append(fmt([rng.randint(0, V) for _ in range(200000)]))
    tests.append(fmt([rng.choice([1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32767]) for _ in range(200000)]))
    tests.append(fmt([rng.randint(0, 8191) for _ in range(150000)]))
    tests.append(fmt([rng.randint(0, 1) * 32767 for _ in range(100000)]))
    tests.append(fmt([rng.randint(0, V) for _ in range(40)]))
    return tests
